// Runs only as the trusted guest bootstrap, after native volume/process verification.
// All identities are generated by the controller; no project script runs as root.
const fs = require('node:fs');
const path = require('node:path');
const input = JSON.parse(Buffer.from(process.argv[2], 'base64').toString('utf8'));
const valid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
if (process.getuid() !== 0 || !valid.test(input.id) || !valid.test(input.attempt)
    || !Number.isInteger(input.uid) || input.uid < 100000 || !/^[0-9a-f]{64}$/.test(input.token)) throw Error('Invalid editor bootstrap');
const shared = '/workspace/shared';
const metadata = path.join(shared, '.firecrab-workspace');
const fail = () => { throw Error('Unexpected private editor file identity'); };
function directory(name, uid, mode) {
    if (!fs.existsSync(name)) fs.mkdirSync(name, {mode});
    const stat = fs.lstatSync(name);
    if (!stat.isDirectory() || stat.uid !== uid) fail();
    fs.chmodSync(name, mode);
}
const root = fs.lstatSync(metadata);
if (!root.isDirectory() || root.uid !== 0 || (root.mode & 0o022)) fail();
const gid = fs.lstatSync(shared).gid;
const parent = path.join(metadata, 'editors');
directory(parent, 0, 0o711);
const editor = path.join(parent, input.id);
directory(editor, 0, 0o711);
const identity = path.join(editor, 'identity.json');
let previous;
try {
    const stat = fs.lstatSync(identity);
    if (!stat.isFile() || stat.uid !== 0 || stat.nlink !== 1 || (stat.mode & 0o077)) fail();
    previous = JSON.parse(fs.readFileSync(identity, 'utf8'));
    if (!Number.isInteger(previous.uid) || previous.uid < 100000) fail();
} catch (error) { if (error.code !== 'ENOENT') throw error; }
const data = path.join(editor, 'data');
if (!fs.existsSync(data)) { fs.mkdirSync(data, {mode:0o700}); fs.chownSync(data,input.uid,gid); }
let visited = 0;
// The API has terminated the previous native UID scope before ownership transfer.
// Reject hard links, devices and sockets other than our stale server socket.
function transfer(name) {
    if (++visited > 100000) throw Error('Editor data entry limit exceeded');
    const stat = fs.lstatSync(name);
    if (stat.uid !== input.uid && stat.uid !== previous?.uid) fail();
    if (stat.isSymbolicLink()) { fs.lchownSync(name,input.uid,gid); return; }
    if (stat.isSocket() && name === path.join(data,'server.sock')) { fs.unlinkSync(name); return; }
    if (!stat.isDirectory() && (!stat.isFile() || stat.nlink !== 1)) fail();
    if (stat.isDirectory()) for (const child of fs.readdirSync(name)) transfer(path.join(name,child));
    fs.chownSync(name,input.uid,gid);
}
transfer(data);
for (const name of ['home','server','user-data','extensions']) {
    const target = path.join(data,name);
    if (!fs.existsSync(target)) { fs.mkdirSync(target,{mode:0o700}); fs.chownSync(target,input.uid,gid); }
    directory(target,input.uid,0o700);
}
function replace(name,bytes,uid) {
    const temporary = name + '.' + input.attempt;
    const fd = fs.openSync(temporary,fs.constants.O_WRONLY|fs.constants.O_CREAT|fs.constants.O_EXCL|fs.constants.O_NOFOLLOW,0o600);
    try { fs.writeFileSync(fd,bytes); fs.fchownSync(fd,uid,gid); fs.fsyncSync(fd); } finally { fs.closeSync(fd); }
    fs.renameSync(temporary,name);
}
replace(path.join(editor,'token'),input.token,input.uid);
replace(identity,JSON.stringify({uid:input.uid,attempt:input.attempt}),0);
// Root-owned parents prevent renaming private homes through the shared project directory.
const fd = fs.openSync(editor,fs.constants.O_RDONLY|fs.constants.O_DIRECTORY|fs.constants.O_NOFOLLOW);
try { fs.fsyncSync(fd); } finally { fs.closeSync(fd); }
console.log('prepared');
